class BizError extends Error {
    messages;
    code;
    data = null;
    constructor(msg, code, data = null) {
        super(msg.join("\n"));
        this.messages = msg;
        this.code = code;
        this.data = data;
    }
}

/** 构造一个结果对象 */
const Result = {
    /** 构造成功结果 */
    Ok: (value) => {
        const result = {
            data: value,
            error: null,
        };
        return result;
    },
    /** 构造失败结果 */
    Err: (message, code, data = null) => {
        const result = {
            data,
            code,
            error: (() => {
                if (Array.isArray(message)) {
                    const e = new BizError(message, code, data);
                    return e;
                }
                if (typeof message === "string") {
                    const e = new BizError([message], code, data);
                    return e;
                }
                if (message instanceof BizError) {
                    return message;
                }
                if (typeof message === "object") {
                    const e = new BizError([message.message], code, data);
                    return e;
                }
                if (!message) {
                    const e = new BizError(["未知错误"], code, data);
                    return e;
                }
                const r = message;
                return r.error;
            })(),
        };
        return result;
    },
};

